// Measured synthetic 17-cube responses, Photoshop 27.3.1. Not Adobe preset files.
// Interpolation is approximate between the measured RGB/slider samples.
const encoded=["","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","",""];
const data=encoded.map(s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0)));
const grid=Array.from({length:17},(_,i)=>Math.round(i*255/16));
const axis=(p:number)=>{let lo=Math.min(15,Math.floor(p/255*16));while(lo>0&&grid[lo]>p)lo--;while(lo<15&&grid[lo+1]<p)lo++;return lo;};
const cached=new Map<string,Float32Array>();
function response(value:number,mode:number){const key=mode+':'+value;let table=cached.get(key);if(table)return table;const p=Math.max(0,Math.min(20,(value+100)/10)),lo=Math.floor(p),hi=Math.min(20,lo+1),f=p-lo,a=data[mode*21+lo],b=data[mode*21+hi];table=new Float32Array(a.length);for(let i=0;i<a.length;i++)table[i]=a[i]+(b[i]-a[i])*f;if(cached.size>=12)cached.delete(cached.keys().next().value!);cached.set(key,table);return table;}
export function applyVibranceResponse(rgb:[number,number,number],value:number,mode:number,out:[number,number,number]) {
 if(!value){out[0]=rgb[0];out[1]=rgb[1];out[2]=rgb[2];return;}
 const table=response(value,mode),r=Math.max(0,Math.min(255,rgb[0]*255)),g=Math.max(0,Math.min(255,rgb[1]*255)),b=Math.max(0,Math.min(255,rgb[2]*255)),rx=axis(r),gx=axis(g),bx=axis(b),rf=(r-grid[rx])/(grid[rx+1]-grid[rx]),gf=(g-grid[gx])/(grid[gx+1]-grid[gx]),bf=(b-grid[bx])/(grid[bx+1]-grid[bx]);let dr=0,dg=0,db=0;
 for(let z=0;z<2;z++)for(let y=0;y<2;y++)for(let x=0;x<2;x++){const rr=rx+x,gg=gx+y,bb=bx+z,i=(rr+17*gg+289*bb)*3,w=(x?rf:1-rf)*(y?gf:1-gf)*(z?bf:1-bf);dr+=(table[i]-grid[rr])*w;dg+=(table[i+1]-grid[gg])*w;db+=(table[i+2]-grid[bb])*w;}
 out[0]=Math.max(0,Math.min(1,(r+dr)/255));out[1]=Math.max(0,Math.min(1,(g+dg)/255));out[2]=Math.max(0,Math.min(1,(b+db)/255));
}
